#!/usr/bin/env node
'use strict';

/**
 * The gate on exam item engineering.
 *
 *   node scripts/check-exam-cues.js            audit every exam content module
 *   node scripts/check-exam-cues.js --stats    print the numbers, never fail
 *
 * This exists because of a specific, measured failure. Version 2 of the
 * Foundations examination was generated by a language model, read well, and was
 * rated highly by a five-persona review. Every one of its forty answer keys was
 * historically correct. It was still unusable, for a reason no reader can see
 * and no proofreader will catch:
 *
 *   the correct answer was strictly the longest option in 38 of 40 items,
 *   so a student who knew nothing and always picked the longest scored 95%.
 *
 * A second cue sat on top of it. Absolutist words, "only", "never", "eliminate",
 * "identical", appeared in 22% of distractors and 2% of keys, so "avoid the
 * option that sounds too strong" was a second free signal pointing the same way.
 *
 * Neither flaw is visible by reading. Both are trivial to measure. That is
 * exactly the shape of failure this repository builds gates for, so the audit
 * runs in the offline suite and a regression fails the push.
 *
 * What it cannot check is whether a key is historically right. That is a
 * judgement about evidence and it stays with the teacher. This file is the
 * mechanical half only, in the same spirit as check-style.js.
 */

const fs = require('fs');
const path = require('path');

const { arrangeExam } = require('./lib/exam-arrange');

const ROOT = path.resolve(__dirname, '..');
const CONTENT_DIR = path.join(ROOT, 'scripts', 'lib', 'exam-content');

const R = '\x1b[31m', G = '\x1b[32m', Y = '\x1b[33m';
const W = '\x1b[1m', D = '\x1b[2m', X = '\x1b[0m';

const statsOnly = process.argv.includes('--stats');

const violations = [];
function fail(examId, rule, detail) {
  violations.push({ examId, rule, detail });
}

/* ── the thresholds, and why each one is where it is ──────────────────────────
 *
 * These are deliberately loose enough that ordinary writing passes. An option
 * set does not have to be typeset to the character; it has to not hand the
 * answer away. Every number below was chosen against the measured V2 failure,
 * so a V2-shaped exam fails every one of them and a well-built exam clears them
 * without the author thinking about it.
 */
const LIMITS = {
  /* Two options whose lengths differ by less than this are the same length as
   * far as a student is concerned. Nobody counts characters; the cue is an
   * option that visibly runs longer than its neighbours, which is roughly a
   * word. Without a band, an item whose key beats the next option by a single
   * character is scored as fully cued, which is not true and would push an
   * author into padding options to no purpose. V2's keys beat the next option
   * by 30 to 100 characters, so the band changes nothing about that verdict. */
  tieBand: 6,
  // Per item: longest option over shortest option. V2 routinely ran 2x to 3x.
  itemSpread: 1.45,
  // Per item: key length over the mean of its distractors. This is the direct
  // form of the cue. 1.0 would be unwritable; 1.25 still leaves no usable signal.
  keyOverDistractors: 1.25,
  // Across the exam, the same ratio on means. V2 was 1.48.
  meanKeyOverDistractors: 1.08,
  // How often the key may be visibly the longest option, meaning longest by
  // more than the tie band. Chance is 25%. V2 was 95%.
  longestKeyRate: 0.40,
  // The naive strategy score. A student who reads nothing and picks the longest
  // option must land near chance, not near an A. Options inside the tie band are
  // scored as a guess among them, because that is what such a student faces.
  pickLongestScore: 0.40,
  // Absolutist markers: the gap in percentage points between how often they
  // appear in keys and in distractors. V2's gap was 20 points.
  absolutistGap: 0.12,
  // Key letter balance: how far any single letter may drift from even.
  keyLetterDrift: 0.10
};

/* Words that make an option sound too strong to be true. A distractor pool
 * saturated with these teaches students to answer by tone rather than by
 * history, which is a habit that transfers to the real exam and hurts them
 * there. Keys are allowed to contain them; what is not allowed is a systematic
 * difference between the two pools. */
const ABSOLUTIST = new RegExp([
  '\\b(only|all|every|everyone|none|never|always|entirely|solely|purely|any)\\b',
  '\\b(eliminat\\w*|prevent\\w*|prohibit\\w*|forbade|forbid\\w*|banned|abolish\\w*)\\b',
  '\\b(identical|uniform\\w*|unanimous\\w*|invariabl\\w*|exclusively|compulsory)\\b',
  '\\b(required|refused|abandoned|replaced|rejected|ceased|halted)\\b'
].join('|'), 'i');

const BANNED_OPTIONS = /^(all|none) of the above\b/i;
const CROSS_REF = /\bquestion\s+\d+\b/i;

/** Visible length. Markup is not what a student reads, so it is stripped before
 *  anything is measured. An option carrying an <em> is not a longer option. */
function visibleLength(s) {
  return String(s).replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim().length;
}

function mean(xs) {
  return xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0;
}

function pct(x) {
  return `${(x * 100).toFixed(0)}%`;
}

/** The audit runs on the delivered arrangement, not the authored one.
 *  scripts/lib/exam-arrange.js is what the builder uses to place options, so
 *  checking anything else would be auditing an exam nobody sits. */
function itemsOf(exam) {
  return arrangeExam(exam);
}

function auditStructure(exam, items) {
  const seen = new Set();
  for (const item of items) {
    const at = `${item.id || '(no id)'}`;
    if (!item.id) fail(exam.id, 'structure', 'an item has no id');
    if (seen.has(item.id)) fail(exam.id, 'structure', `duplicate item id "${item.id}"`);
    seen.add(item.id);

    if (!item.stem || !String(item.stem).trim()) {
      fail(exam.id, 'structure', `${at}: empty stem`);
    }

    const letters = Object.keys(item.choices || {}).sort();
    if (letters.join('') !== 'ABCD') {
      fail(exam.id, 'structure', `${at}: needs exactly choices A, B, C, D (found ${letters.join('') || 'none'})`);
      continue;
    }

    if (!letters.includes(item.key)) {
      fail(exam.id, 'structure', `${at}: key "${item.key}" is not one of the choices`);
    }

    const texts = letters.map(l => String(item.choices[l]).trim().toLowerCase());
    if (new Set(texts).size !== texts.length) {
      fail(exam.id, 'structure', `${at}: two options are the same text`);
    }

    for (const l of letters) {
      if (BANNED_OPTIONS.test(String(item.choices[l]).trim())) {
        fail(exam.id, 'options', `${at}: "${item.choices[l]}" is not a real option`);
      }
    }

    // V2's question 26 said "the interpretation in Question 25". Canvas shuffles
    // question order whenever a teacher opens a make-up window, and the
    // reference then points at nothing. An item has to stand on its own.
    const surfaces = [item.stem, ...letters.map(l => item.choices[l]), item.set.passage || '', item.set.instruction || ''];
    for (const s of surfaces) {
      if (CROSS_REF.test(String(s))) {
        fail(exam.id, 'cross-reference', `${at}: refers to another item by number ("${String(s).match(CROSS_REF)[0]}"), which breaks under shuffle`);
        break;
      }
    }
  }
}

function auditLength(exam, items) {
  const keyLens = [];
  const disLens = [];
  let visiblyLongestKey = 0;
  let pickLongestScore = 0;

  for (const item of items) {
    const letters = Object.keys(item.choices || {});
    if (letters.length !== 4 || !letters.includes(item.key)) continue;

    const lens = {};
    for (const l of letters) lens[l] = visibleLength(item.choices[l]);

    const kl = lens[item.key];
    const others = letters.filter(l => l !== item.key).map(l => lens[l]);
    keyLens.push(kl);
    disLens.push(...others);

    const max = Math.max(...Object.values(lens));
    const min = Math.min(...Object.values(lens));

    // Everything within the tie band of the longest looks equally long on the
    // page, so a student picking "the longest" is really guessing among these.
    const tied = Object.values(lens).filter(v => v >= max - LIMITS.tieBand).length;
    const keyIsTiedLongest = kl >= max - LIMITS.tieBand;

    if (keyIsTiedLongest && tied === 1) visiblyLongestKey++;
    if (keyIsTiedLongest) pickLongestScore += 1 / tied;

    const spread = min ? max / min : Infinity;
    if (spread > LIMITS.itemSpread) {
      fail(exam.id, 'length spread',
        `${item.id}: longest option is ${spread.toFixed(2)}x the shortest (limit ${LIMITS.itemSpread}). ` +
        `Lengths ${letters.sort().map(l => `${l}=${lens[l]}`).join(' ')}`);
    }

    const ratio = mean(others) ? kl / mean(others) : Infinity;
    if (ratio > LIMITS.keyOverDistractors) {
      fail(exam.id, 'key length',
        `${item.id}: key is ${ratio.toFixed(2)}x the mean distractor (limit ${LIMITS.keyOverDistractors}). ` +
        `Key ${item.key}=${kl}, distractors ${others.join(', ')}`);
    }
  }

  const n = items.length || 1;
  const meanRatio = mean(disLens) ? mean(keyLens) / mean(disLens) : Infinity;
  if (meanRatio > LIMITS.meanKeyOverDistractors) {
    fail(exam.id, 'key length',
      `across the exam the mean key is ${meanRatio.toFixed(2)}x the mean distractor (limit ${LIMITS.meanKeyOverDistractors})`);
  }

  if (visiblyLongestKey / n > LIMITS.longestKeyRate) {
    fail(exam.id, 'longest-answer cue',
      `the key is visibly the longest option in ${visiblyLongestKey}/${n} items (${pct(visiblyLongestKey / n)}), limit ${pct(LIMITS.longestKeyRate)}. Chance is 25%.`);
  }

  if (pickLongestScore / n > LIMITS.pickLongestScore) {
    fail(exam.id, 'longest-answer cue',
      `a student who reads nothing and always picks the longest option scores ${pickLongestScore.toFixed(1)}/${n} (${pct(pickLongestScore / n)}), limit ${pct(LIMITS.pickLongestScore)}`);
  }

  return {
    meanKey: mean(keyLens),
    meanDistractor: mean(disLens),
    meanRatio,
    longestKey: visiblyLongestKey,
    pickLongestScore,
    n
  };
}

function auditAbsolutist(exam, items) {
  let keyHits = 0, keyN = 0, disHits = 0, disN = 0;

  for (const item of items) {
    const letters = Object.keys(item.choices || {});
    if (letters.length !== 4 || !letters.includes(item.key)) continue;

    const keyAbs = ABSOLUTIST.test(String(item.choices[item.key]));
    keyN++; if (keyAbs) keyHits++;

    const disAbs = letters.filter(l => l !== item.key).map(l => ABSOLUTIST.test(String(item.choices[l])));
    disN += disAbs.length;
    disHits += disAbs.filter(Boolean).length;

    // The single most exploitable shape: three strong-sounding wrong answers and
    // one measured right one. A student crosses off by tone and never reads the
    // history.
    if (disAbs.every(Boolean) && !keyAbs) {
      fail(exam.id, 'absolutist cue',
        `${item.id}: all three distractors use absolutist language and the key does not, so the item is answerable by tone alone`);
    }
  }

  const keyRate = keyN ? keyHits / keyN : 0;
  const disRate = disN ? disHits / disN : 0;
  const gap = disRate - keyRate;

  if (gap > LIMITS.absolutistGap) {
    fail(exam.id, 'absolutist cue',
      `absolutist language appears in ${pct(disRate)} of distractors but only ${pct(keyRate)} of keys, ` +
      `a gap of ${(gap * 100).toFixed(0)} points (limit ${(LIMITS.absolutistGap * 100).toFixed(0)})`);
  }

  return { keyRate, disRate, gap };
}

function auditKeyBalance(exam, items) {
  const counts = { A: 0, B: 0, C: 0, D: 0 };
  for (const item of items) if (counts[item.key] !== undefined) counts[item.key]++;
  const n = items.length || 1;

  for (const [letter, c] of Object.entries(counts)) {
    const drift = Math.abs(c / n - 0.25);
    if (drift > LIMITS.keyLetterDrift) {
      fail(exam.id, 'key balance',
        `answer ${letter} is the key ${c}/${n} times (${pct(c / n)}), more than ${pct(LIMITS.keyLetterDrift)} off even`);
    }
  }
  return counts;
}

/** Every stimulus image must be a real file. V2 shipped three items telling
 *  students to read a Southern Song map, pointed at foundations-5.svg, which is
 *  the six AP regions map and shows no Yangtze, no Lin'an and no Quanzhou. The
 *  alt text describing the Song map was written to match a plausible filename.
 *  A file-existence check would not have caught that one, but a missing file is
 *  the cheaper half of the same failure and there is no reason to ship it. */
function auditStimuli(exam) {
  for (const set of exam.sets || []) {
    if (!set.image) continue;
    const rel = String(set.image.src || '');
    if (!rel) { fail(exam.id, 'stimulus', `set ${set.id}: image with no src`); continue; }
    const abs = path.join(ROOT, rel);
    if (!fs.existsSync(abs)) {
      fail(exam.id, 'stimulus', `set ${set.id}: image "${rel}" does not exist in the repository`);
    }
    if (!set.image.alt || !String(set.image.alt).trim()) {
      fail(exam.id, 'stimulus', `set ${set.id}: image has no alt text`);
    }
    // Nothing in an exam may depend on a third party being reachable during the
    // exam. Two of V2's four stimuli hotlinked commons.wikimedia.org, which
    // returned HTTP 429 under test.
    if (/^https?:/i.test(rel)) {
      fail(exam.id, 'stimulus', `set ${set.id}: image is a remote URL. Exam images must be repository files.`);
    }
  }
}

/** Coverage against the learning targets, declared by the exam itself.
 *
 *  V2 tested none of the six AP regions by name, never made Christianity,
 *  Hinduism, Daoism or Islam a correct answer, and never made the Mediterranean
 *  sea lanes one either, while spending three items on a mislabelled map. Every
 *  one of those is in a stated Foundations learning target. A coverage
 *  declaration turns that from something you notice in June into something the
 *  push refuses. */
function auditCoverage(exam, items) {
  const byTarget = new Map();
  for (const item of items) {
    const t = item.target || '(untagged)';
    byTarget.set(t, (byTarget.get(t) || 0) + 1);
    if (!item.target) fail(exam.id, 'coverage', `${item.id}: no target declared`);
  }

  for (const [target, min] of Object.entries(exam.coverage || {})) {
    const got = byTarget.get(target) || 0;
    if (got < min) {
      fail(exam.id, 'coverage', `${target} has ${got} items, the exam declares a minimum of ${min}`);
    }
  }

  // Terms that must reach a student as something true, not only as a wrong
  // answer to cross off. Appearing in a key or in the stem of the item it
  // belongs to both count; appearing only in distractors does not.
  for (const term of exam.requiredInKeys || []) {
    const re = new RegExp(term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    const hit = items.some(item => re.test(String(item.choices[item.key])) || re.test(String(item.stem)));
    if (!hit) {
      fail(exam.id, 'coverage', `"${term}" never appears in a correct answer or a stem, only ever as something to reject`);
    }
  }

  return byTarget;
}

// ── run ───────────────────────────────────────────────────────────────────────

if (!fs.existsSync(CONTENT_DIR)) {
  console.error(`No exam content directory at ${path.relative(ROOT, CONTENT_DIR)}`);
  process.exit(1);
}

const files = fs.readdirSync(CONTENT_DIR).filter(f => f.endsWith('.js')).sort();
if (!files.length) {
  console.error('check-exam-cues found no exam content modules, which is itself a failure.');
  process.exit(1);
}

console.log(`\n${W}Exam item engineering${X}\n`);

for (const name of files) {
  const exam = require(path.join(CONTENT_DIR, name));
  const items = itemsOf(exam);

  auditStructure(exam, items);
  const len = auditLength(exam, items);
  const abs = auditAbsolutist(exam, items);
  const keys = auditKeyBalance(exam, items);
  auditStimuli(exam);
  const cov = auditCoverage(exam, items);

  const mine = violations.filter(v => v.examId === exam.id);
  const mark = mine.length ? `${R}✗${X}` : `${G}✓${X}`;
  console.log(`  ${mark} ${W}${exam.id}${X} ${D}(${items.length} items, ${(exam.sets || []).length} stimulus sets)${X}`);
  console.log(`      ${D}pick-the-longest scores ${len.pickLongestScore.toFixed(1)}/${len.n} (${pct(len.pickLongestScore / len.n)}), chance 25%${X}`);
  console.log(`      ${D}key visibly longest in ${len.longestKey}/${len.n}; mean key ${len.meanKey.toFixed(0)} vs distractor ${len.meanDistractor.toFixed(0)} chars (${len.meanRatio.toFixed(2)}x)${X}`);
  console.log(`      ${D}absolutist language: keys ${pct(abs.keyRate)}, distractors ${pct(abs.disRate)}, gap ${(abs.gap * 100).toFixed(0)} points${X}`);
  console.log(`      ${D}keys A=${keys.A} B=${keys.B} C=${keys.C} D=${keys.D}${X}`);
  console.log(`      ${D}coverage ${[...cov.entries()].sort().map(([k, v]) => `${k}:${v}`).join(' ')}${X}`);
}

console.log(`\n${'─'.repeat(64)}`);

if (statsOnly) {
  console.log(`${Y}--stats: ${violations.length} finding(s), not failing the run.${X}`);
  for (const v of violations) console.log(`  ${Y}[${v.rule}]${X} ${v.detail}`);
  process.exit(0);
}

if (violations.length) {
  const byRule = new Map();
  for (const v of violations) {
    if (!byRule.has(v.rule)) byRule.set(v.rule, []);
    byRule.get(v.rule).push(v);
  }
  for (const [rule, list] of byRule) {
    console.error(`\n${R}${W}${rule}${X} ${D}(${list.length})${X}`);
    for (const v of list) console.error(`  ${v.detail}`);
  }
  console.error(`\n${R}${W}${violations.length} item-engineering violation${violations.length === 1 ? '' : 's'}.${X}`);
  console.error(`${D}Edit the exam content module, then run: npm run build:exam${X}`);
  process.exit(1);
}

console.log(`${G}${W}Exam items carry no measurable answer cue.${X}`);
